from confluent_kafka import Consumer

c = Consumer({
    'bootstrap.servers': 'localhost:9092',
    'group.id': 'billing-service',
    'auto.offset.reset': 'earliest',
})
c.subscribe(['orders'])

while True:
    msg = c.poll(1.0)
    if msg is None or msg.error():
        continue
    print(f'Got {msg.value()} at offset {msg.offset()}')
    c.commit(msg)
